using System;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;

namespace AsyncProgrammingDemo
{
    class Program
    {
        static async Task Main(string[] args)
        {
            Console.WriteLine("Starting async operations...");

            // Run multiple async operations concurrently
            var task1 = DownloadDataAsync("https://api.example.com/data1");
            var task2 = DownloadDataAsync("https://api.example.com/data2");
            var task3 = ProcessDataAsync("Sample data");

            // Wait for all tasks to complete
            await Task.WhenAll(task1, task2, task3);

            Console.WriteLine("All operations completed!");
        }

        static async Task<string> DownloadDataAsync(string url)
        {
            Console.WriteLine($"Starting download from {url}");

            // Simulate network delay
            await Task.Delay(2000);

            Console.WriteLine($"Download completed from {url}");
            return $"Data from {url}";
        }

        static async Task<string> ProcessDataAsync(string data)
        {
            Console.WriteLine($"Processing: {data}");

            // Simulate processing time
            await Task.Delay(1500);

            Console.WriteLine($"Processing completed for: {data}");
            return $"Processed: {data}";
        }

        // Example of async method with cancellation support
        static async Task LongRunningOperationAsync(CancellationToken cancellationToken)
        {
            for (int i = 0; i < 10; i++)
            {
                cancellationToken.ThrowIfCancellationRequested();

                Console.WriteLine($"Processing step {i + 1}");
                await Task.Delay(1000, cancellationToken);
            }
        }

        // Example of async method with exception handling
        static async Task<string> SafeAsyncOperation()
        {
            try
            {
                await Task.Delay(1000);
                // Simulate potential error
                if (new Random().Next(0, 2) == 0)
                    throw new InvalidOperationException("Simulated error");

                return "Operation successful";
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error occurred: {ex.Message}");
                return "Operation failed";
            }
        }
    }
}
```

**How to Use Async/Await in C#:**

1. **Async Keyword**: Mark methods with `async` to enable await usage
2. **Await Keyword**: Use `await` to asynchronously wait for task completion
3. **Task Return Types**: Return `Task`, `Task<T>`, or `ValueTask<T>` from async methods
4. **Task.WhenAll**: Run multiple tasks concurrently and wait for all to complete
5. **Task.WhenAny**: Wait for the first task to complete
6. **CancellationToken**: Support cancellation in long-running operations
7. **Exception Handling**: Use try-catch blocks around await calls
8. **ConfigureAwait**: Use `ConfigureAwait(false)` in library code to avoid deadlocks

**Key Benefits:**
- Non-blocking operations
- Better responsiveness in UI applications
- Improved scalability in server applications
- Cleaner code compared to traditional threading

